python3 -c "import copy
def test_consume_stock():
    stock = {"apple": 10, "banana": 5}
    requests = [("apple", 3), ("banana", 2)]
    try:
        consume_stock(stock, requests)
    except Exception as e:
        print("Error:", e)
    else:
        assert stock == {"apple": 7, "banana": 3}, "Stock not updated correctly"
    # Test unknown item
    stock = {"apple": 10}
    requests = [("orange", 2)]
    try:
        consume_stock(stock, requests)
    except KeyError as e:
        print("KeyError caught:", e)
    else:
        assert stock == {"apple": 10}, "Stock should not change on error"
    # Test negative quantity
    stock = {"apple": 10}
    requests = [("apple", -2)]
    try:
        consume_stock(stock, requests)
    except ValueError as e:
        print("ValueError caught:", e)
    else:
        assert stock == {"apple": 10}, "Stock should not change on error"
    # Test insufficient stock
    stock = {"apple": 10}
    requests = [("apple", 15)]
    try:
        consume_stock(stock, requests)
    except ValueError as e:
        print("ValueError caught:", e)
    else:
        assert stock == {"apple": 10}, "Stock should not change on error"
    # Test empty requests
    stock = {"apple": 10}
    requests = []
    consume_stock(stock, requests)
    assert stock == {"apple": 10}, "Stock should remain unchanged for empty requests"
    print("All tests passed.")
test_consume_stock()"
